def arr(name, typ, vals, w):
    rows = []
    for i in range(0, len(vals), 8):
        rows.append("        " + ", ".join('"' + format(v & ((1 << w) - 1), "0" + str(w) + "b") + '"' for v in vals[i:i + 8]))
    return "    constant " + name + " : " + typ + " := (\n" + ",\n".join(rows) + "\n    );"


